import { createRouter, createWebHistory } from "vue-router";
import { useUserStore } from "@/stores/user.ts";
import { useWebStyleStore } from "@/stores/webStyle";
import { useSidebarStyleStore } from "@/stores/sidebarStyle";
import { makeTabRouter } from "@/config/tab-config";
import { makeViewRouter, getTabSubMenus } from "@/config/view-config";
import { preloadEditorExtensions } from "@/util/md-extensions";

import type { RouteRecordRaw } from "vue-router";
import View403 from "@/views/View403.vue";
// 路由级代码分割：404 页面使用动态导入
const View404 = () => import("@/views/View404.vue");

const routers = [] as RouteRecordRaw[];

// 含 md-editor-v3 的路由：进入这些页面时后台预热 mermaid/prettier/cropper 等重依赖，
// 让工具栏动作（格式化、图片裁剪）与后续挂载的组件无需再等待。
//
// 这里只是性能优化，不是正确性开关：
// 公式渲染的正确性由 main.ts 中 MdPreview/MdEditor 异步加载器 await ensureKatex() 保证，
// 因此本名单即使遗漏路由，也只会变慢，不会出现公式加载不出来的问题。
const EDITOR_ROUTES = new Set([
  // MdEditor 直接渲染的页面
  "manage-problem",
  "manage-problem-create",
  "manage-problem-daily",
  "manage-problem-daily-create",
  "manage-web",
  "collection-edit",
  "collection-create",
  "contest-edit",
  "contest-create",
  "discuss-edit",
  "discuss-create",
  "manage-bot-game",
  // 含内联回复编辑器的详情页（编辑器由 v-if 控制，预热可避免点击后长时间等待）
  "discuss-detail",
  "contest-discuss-detail",
  "bot-about",
  "system-about",
]);

makeTabRouter(routers);
makeViewRouter(routers);

routers.push({
  path: "/403",
  name: "403",
  component: View403,
});

routers.push({
  path: "/:pathMatch(.*)*",
  name: "404",
  component: View404,
});

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes: routers,
});

router.beforeEach((to, _, next) => {
  if (to.name == null || !router.hasRoute(to.name)) {
    next({ name: "home" });
    return;
  }

  const toMeta = to.matched[to.matched.length - 1].meta;
  if (toMeta.redirect) {
    next({ name: toMeta.redirect as string });
    return;
  }

  if (toMeta.needLogin) {
    const userStore = useUserStore();
    if (!userStore.isLogin()) {
      next({ name: "login", query: { redirect_uri: to.fullPath } });
      return;
    }
  }

  const auths = toMeta.tabAuths as string[] | undefined;
  if (auths) {
    const userStore = useUserStore();
    if (!userStore.hasAllAuths(auths)) {
      next({ name: "403", query: { target: to.fullPath } });
      return;
    }
  }

  next();
});

router.afterEach((to: any, from: any) => {
  if (to.name === from.name) {
    return;
  }

  // 进入需要 markdown 编辑器的页面时，后台预热 md-editor-v3 重依赖
  if (EDITOR_ROUTES.has(to.name as string)) {
    preloadEditorExtensions();
  }

  const sidebarStyleStore = useSidebarStyleStore();
  const webStyleStore = useWebStyleStore();

  let toMeta = null;
  if (to.matched.length > 0) {
    toMeta = to.matched[to.matched.length - 1].meta;
  }
  // let fromMeta = null;
  // if (from.matched.length > 0) {
  //   fromMeta = from.matched[from.matched.length - 1].meta;
  // }

  if (toMeta?.title) {
    webStyleStore.setRouteTitle(toMeta?.title as string);
    webStyleStore.setTitle(toMeta?.title as string);
  }

  if (toMeta?.showSidebar) {
    sidebarStyleStore.setSidebarShow(true);
    const menus = getTabSubMenus(toMeta?.sidebar, toMeta?.tab as string);
    sidebarStyleStore.setMenuList(menus);
    sidebarStyleStore.setMenuActiveName(toMeta?.sidebar as string);
  } else {
    sidebarStyleStore.setSidebarShow(false);
  }
  window.scrollTo(0, 0);
});

export default router;
